const pacificYearMonth=(now=new Date())=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'numeric'}).formatToParts(now);return {year:Number(parts.find(part=>part.type==='year').value),month:Number(parts.find(part=>part.type==='month').value)};};
export class PostgresAriveRepository {
  constructor(pool){this.pool=pool;this.calendar=defaultCalendar;}
  async initialize(){const {readFile}=await import('node:fs/promises');await this.pool.query('create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())');for(const migration of [['001_initial','../../db/schema.sql'],['002_assistant_milestones','../../db/002_assistant_milestones.sql'],['003_remove_payoff_milestones','../../db/003_remove_payoff_milestones.sql'],['004_repair_processor_assistant_role','../../db/004_repair_processor_assistant_role.sql'],['005_processing_pipeline_eligibility','../../db/005_processing_pipeline_eligibility.sql'],['006_bootstrap_in_flight_processing_eligibility','../../db/006_bootstrap_in_flight_processing_eligibility.sql'],['007_protect_kpis_from_preexisting_history','../../db/007_protect_kpis_from_preexisting_history.sql'],['008_correct_sla_ownership','../../db/008_correct_sla_ownership.sql'],['009_monthly_funding_goals','../../db/009_monthly_funding_goals.sql'],['010_historical_funding_corrections','../../db/010_historical_funding_corrections.sql'],['011_closing_disclosure_sent','../../db/011_closing_disclosure_sent.sql'],['012_workflow_task_engine','../../db/012_workflow_task_engine.sql'],['013_employee_auth','../../db/013_employee_auth.sql'],['014_victory_events','../../db/014_victory_events.sql'],['015_interactive_workflow_actions','../../db/015_interactive_workflow_actions.sql']]){const applied=await this.pool.query('select name from schema_migrations where name=$1',[migration[0]]);if(applied.rowCount)continue;const client=await this.pool.connect();try{await client.query('begin');await client.query(await readFile(new URL(migration[1],import.meta.url),'utf8'));await client.query('insert into schema_migrations (name) values ($1)',[migration[0]]);await client.query('commit');}catch(error){await client.query('rollback');throw error;}finally{client.release();}}const holidays=await this.pool.query(`select h.holiday_date::text holiday_date from calendar_holidays h join business_calendars c on c.id=h.calendar_id where c.name='HFN' order by h.holiday_date`);this.calendar={...defaultCalendar,holidays:holidays.rows.map(row=>row.holiday_date)};setHfnBusinessCalendar(this.calendar);await this.repairAssistantDeadlines();await this.repairClosingDisclosureTasks();}
  assistantDeadline(submittedAt,milestone){return dueAt(submittedAt,{kind:'businessHours',value:milestone.businessDays*8.5},this.calendar).toISOString();}
  async repairAssistantDeadlines(){const tasks=await this.pool.query(`select t.id,t.task_type,e.occurred_at from assistant_tasks t join loan_stage_events e on e.id=t.created_from_event_id where e.event_type='UNDERWRITING_SUBMITTED'`);for(const task of tasks.rows){const milestone=assistantMilestones.find(item=>item.type===task.task_type);if(!milestone)continue;const dueAt=this.assistantDeadline(task.occurred_at,milestone);await this.pool.query('update assistant_tasks set due_at=$2 where id=$1 and due_at is distinct from $2',[task.id,dueAt]);}}
  async syncClosingDisclosureTask(executor,loanId,createdFromEventId,milestoneDates){const applicableAt=milestoneDates.appraisalReceivedDate,completedAt=milestoneDates.initialCDSentDate??null;if(!applicableAt){if(completedAt)await executor.query(`update assistant_tasks set completed_at=coalesce(completed_at,$2),status=case when coalesce(completed_at,$2)<=due_at then 'completed_within_sla' else 'completed_late' end where loan_id=$1 and task_type='closing_disclosure_sent'`,[loanId,completedAt]);return 0;}const dueAtValue=dueAt(applicableAt,{kind:'businessHours',value:17},this.calendar).toISOString(),status=completedAt?(new Date(completedAt)<=new Date(dueAtValue)?'completed_within_sla':'completed_late'):'open';const result=await executor.query(`insert into assistant_tasks (id,loan_id,task_type,applicable_at,due_at,completed_at,status,created_from_event_id) values ($1,$2,'closing_disclosure_sent',$3,$4,$5,$6,$7) on conflict (loan_id,task_type) do update set completed_at=coalesce(assistant_tasks.completed_at,excluded.completed_at),status=case when coalesce(assistant_tasks.completed_at,excluded.completed_at) is null then assistant_tasks.status when coalesce(assistant_tasks.completed_at,excluded.completed_at)<=assistant_tasks.due_at then 'completed_within_sla' else 'completed_late' end returning (xmax=0) inserted`,[randomUUID(),loanId,applicableAt,dueAtValue,completedAt,status,createdFromEventId]);return result.rows?.[0]?.inserted?1:0;}
  async repairClosingDisclosureTasks(){const snapshots=await this.pool.query(`select l.id loan_id,nullif(i.payload->'milestoneDates'->>'appraisalReceivedDate','') appraisal_received_date,nullif(i.payload->'milestoneDates'->>'initialCDSentDate','') initial_cd_sent_date from loans l join lateral (select payload from inbound_events i where i.source='zapier-arive' and i.payload->>'ariveSystemGuid'=l.arive_system_guid order by i.received_at desc,i.id desc limit 1) i on true`);for(const snapshot of snapshots.rows)await this.syncClosingDisclosureTask(this.pool,snapshot.loan_id,null,{appraisalReceivedDate:snapshot.appraisal_received_date,initialCDSentDate:snapshot.initial_cd_sent_date});}
  async addWorkflowHistory(executor,taskId,{at,action,fromState=null,toState=null,actorEmail=null,note=null,metadata={}}){await executor.query('insert into workflow_task_history(id,task_id,occurred_at,action,from_state,to_state,actor_email,note,metadata) values($1,$2,$3,$4,$5,$6,$7,$8,$9)',[randomUUID(),taskId,at,action,fromState,toState,actorEmail,note,safeWorkflowMetadata(metadata)]);}
  async syncWorkflowForEvent(executor,{loanId,eventType,occurredAt,eventId,processor,processorEmail,assistant,assistantEmail}){const tracking=await executor.query('select kpi_tracking_started_at is not null kpi_eligible from loans where id=$1',[loanId]),kpiEligible=Boolean(tracking.rows[0]?.kpi_eligible);for(const definition of definitionsCompletedBy(eventType)){const completed=await executor.query(`update workflow_tasks set state='completed',completed_at=$3,updated_at=now() where loan_id=$1 and task_type=$2 and state not in ('completed','cancelled','not_applicable') returning id,state`,[loanId,definition.type,occurredAt]);for(const task of completed.rows)await this.addWorkflowHistory(executor,task.id,{at:occurredAt,action:'completed_by_arive_event',fromState:task.state,toState:'completed',metadata:{sourceEvent:eventType}});}for(const definition of definitionsForTrigger(eventType)){const owner=definition.ownerRole==='processor'?{email:processorEmail,name:processor}:{email:assistantEmail,name:assistant},dueAtValue=businessDeadline(occurredAt,definition.businessDays,this.calendar),created=await executor.query(`insert into workflow_tasks(id,loan_id,task_type,title,origin,owner_role,owner_email,owner_name,source_trigger,state,created_at,due_at,kpi_eligible,waiting_on,follow_up_cadence_business_days,metadata) values($1,$2,$3,$4,'automatic',$5,$6,$7,$8,'action_required',$9,$10,$11,$12,$13,$14) on conflict(loan_id,task_type) do nothing returning id`,[randomUUID(),loanId,definition.type,definition.title,definition.ownerRole,owner.email??null,owner.name??null,eventType,occurredAt,dueAtValue,kpiEligible,definition.waitingOn??null,definition.followUpBusinessDays??null,{}]);for(const task of created.rows){await this.addWorkflowHistory(executor,task.id,{at:occurredAt,action:'created',toState:'action_required',metadata:{sourceEvent:eventType}});for(const [sortOrder,label] of (definition.checklist??[]).entries())await executor.query('insert into workflow_task_checklist_items(id,task_id,label,sort_order) values($1,$2,$3,$4)',[randomUUID(),task.id,label,sortOrder]);}}if(eventType==='LOAN_FUNDED'){const cancelled=await executor.query(`update workflow_tasks set state='cancelled',updated_at=now() where loan_id=$1 and state not in ('completed','cancelled','not_applicable') returning id,state`,[loanId]);for(const task of cancelled.rows)await this.addWorkflowHistory(executor,task.id,{at:occurredAt,action:'cancelled_by_funding',fromState:task.state,toState:'cancelled',metadata:{sourceEvent:eventType}});}}
  async createWorkflowTask({loanId,taskType,title,ownerRole,ownerEmail=null,ownerName=null,origin='manual',createdAt=new Date().toISOString(),businessDays=null,kpiEligible=false,waitingOn=null,followUpBusinessDays=null,metadata={}}){if(!['manual','conditional'].includes(origin)||!['processor','processor_assistant','loan_officer','management','system'].includes(ownerRole)||!loanId||!taskType||!title)throw new Error('Invalid workflow task');const dueAtValue=businessDeadline(createdAt,businessDays,this.calendar),result=await this.pool.query(`insert into workflow_tasks(id,loan_id,task_type,title,origin,owner_role,owner_email,owner_name,state,created_at,due_at,kpi_eligible,waiting_on,follow_up_cadence_business_days,metadata) values($1,$2,$3,$4,$5,$6,$7,$8,'action_required',$9,$10,$11,$12,$13,$14) returning *`,[randomUUID(),loanId,taskType,title,origin,ownerRole,ownerEmail,ownerName,createdAt,dueAtValue,kpiEligible,waitingOn,followUpBusinessDays,safeWorkflowMetadata(metadata)]);await this.addWorkflowHistory(this.pool,result.rows[0].id,{at:createdAt,action:'created',toState:'action_required'});return result.rows[0];}
  async transitionWorkflowTask(taskId,{state,at=new Date().toISOString(),actorEmail=null,note=null,blockedReason=null}){if(!workflowTaskStates.includes(state))throw new Error('Invalid workflow task state');const result=await this.pool.query(`update workflow_tasks set state=$2,completed_at=case when $2='completed' then $3 else completed_at end,blocked_at=case when $2='blocked' then $3 else blocked_at end,blocked_reason=case when $2='blocked' then $4 else blocked_reason end,blocked_by_email=case when $2='blocked' then $5 else blocked_by_email end,updated_at=now() where id=$1 returning id,state`,[taskId,state,at,blockedReason,actorEmail]);if(!result.rowCount)return null;await this.addWorkflowHistory(this.pool,taskId,{at,action:'state_changed',toState:state,actorEmail,note});return result.rows[0];}
  async recordWorkflowFollowUp(taskId,{at=new Date().toISOString(),actorEmail=null,note=null}){const task=await this.pool.query('select * from workflow_tasks where id=$1',[taskId]);if(!task.rowCount)throw new Error('Workflow task not found');const row=task.rows[0];if(!row.follow_up_cadence_business_days)throw new Error('Task has no follow-up cadence');const nextAt=nextFollowUpAt(at,row.follow_up_cadence_business_days,this.calendar),updated=await this.pool.query(`update workflow_tasks set state='waiting',last_follow_up_at=$2,next_follow_up_at=$3,follow_up_count=follow_up_count+1,updated_at=now() where id=$1 returning *`,[taskId,at,nextAt]);await this.addWorkflowHistory(this.pool,taskId,{at,action:'follow_up_recorded',toState:'waiting',actorEmail,note});return updated.rows[0];}
  async updateWorkflowChecklistItem(itemId,{state,at=new Date().toISOString(),actorEmail=null}){if(!['completed','not_applicable','action_required'].includes(state))throw new Error('Invalid checklist state');const result=await this.pool.query(`update workflow_task_checklist_items set state=$2,completed_at=case when $2 in ('completed','not_applicable') then $3 else null end,completed_by_email=case when $2 in ('completed','not_applicable') then $4 else null end where id=$1 returning task_id`,[itemId,state,at,actorEmail]);if(!result.rowCount)return null;const items=await this.pool.query('select state from workflow_task_checklist_items where task_id=$1',[result.rows[0].task_id]);if(checklistComplete(items.rows))await this.transitionWorkflowTask(result.rows[0].task_id,{state:'completed',at,actorEmail,note:'Checklist complete'});return result.rows[0];}
  async findActiveEmployeeByEmail(email){const result=await this.pool.query(`select id,email,display_name "displayName",role from employees where email=lower($1) and active=true`,[email]);return result.rows[0]??null;}
  async createOidcLoginState({stateHash,codeVerifier,nonce,expiresAt}){await this.pool.query('insert into oidc_login_states(state_hash,code_verifier,nonce,expires_at) values($1,$2,$3,$4)',[stateHash,codeVerifier,nonce,expiresAt]);}
  async consumeOidcLoginState(stateHash){const result=await this.pool.query('delete from oidc_login_states where state_hash=$1 returning *',[stateHash]);return result.rows[0]??null;}
  async createSession({sessionHash,employeeId,expiresAt}){await this.pool.query('insert into auth_sessions(id,session_hash,employee_id,expires_at) values($1,$2,$3,$4)',[randomUUID(),sessionHash,employeeId,expiresAt]);}
  async findSessionByHash(sessionHash){const result=await this.pool.query(`select e.id,e.email,e.display_name "displayName",e.role from auth_sessions s join employees e on e.id=s.employee_id where s.session_hash=$1 and s.expires_at>now() and e.active=true`,[sessionHash]);return result.rows[0]??null;}
  async deleteSession(sessionHash){await this.pool.query('delete from auth_sessions where session_hash=$1',[sessionHash]);}
  async processorWorkQueue({employee,ownerEmail=null}){if(employee.role!=='processor'&&employee.role!=='admin')throw new Error('Processor My Work is not available for this role');const owner=employee.role==='admin'&&ownerEmail?String(ownerEmail).toLowerCase():employee.role==='admin'?null:employee.email,params=[],ownerWhere=owner?(params.push(owner),`and lower(t.owner_email)=$${params.length}`):'';const result=await this.pool.query(`select t.id,t.task_type "taskType",t.title,t.state,t.due_at "dueAt",t.next_follow_up_at "nextFollowUpAt",t.waiting_on "waitingOn",t.owner_email "ownerEmail",l.arive_display_loan_id "displayLoanId",l.current_stage "currentStage",coalesce(e.metadata->>'assistant','') assistant from workflow_tasks t join loans l on l.id=t.loan_id left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where t.owner_role='processor' and t.state not in ('completed','cancelled','not_applicable') ${ownerWhere} order by case when t.state='past_due' or (t.due_at is not null and t.due_at<now()) then 0 when t.state in ('action_required','follow_up_due') then 1 when t.state='due_soon' then 2 when t.state='waiting' then 3 when t.state='blocked' then 4 else 5 end,coalesce(t.next_follow_up_at,t.due_at) asc nulls last`,params);return {viewer:{email:employee.email,role:employee.role},tasks:result.rows.map(row=>({...row,priority:row.state==='past_due'||(row.dueAt&&new Date(row.dueAt)<new Date())?'past_due':row.state}))};}
  async myWorkQueue({employee,ownerEmail=null}){if(!['processor','processor_assistant','admin'].includes(employee.role))throw new Error('My Work is not available for this role');const owner=employee.role==='admin'&&ownerEmail?String(ownerEmail).toLowerCase():employee.role==='admin'?null:employee.email,params=[],ownerWhere=owner?(params.push(owner),`and lower(t.owner_email)=$${params.length}`):'';const result=await this.pool.query(`select t.id,t.task_type "taskType",t.title,t.state,t.owner_role "ownerRole",t.owner_email "ownerEmail",t.owner_name "ownerName",t.due_at "dueAt",t.next_follow_up_at "nextFollowUpAt",t.last_follow_up_at "lastFollowUpAt",t.follow_up_count "followUpCount",t.follow_up_cadence_business_days "followUpCadenceBusinessDays",t.waiting_on "waitingOn",t.blocked_category "blockedCategory",t.blocked_reason "blockedReason",l.arive_display_loan_id "displayLoanId",l.current_stage "currentStage",coalesce(e.metadata->>'processor','Unassigned') processor,coalesce(e.metadata->>'assistant','Unassigned') assistant,(select count(*) from workflow_task_checklist_items i where i.task_id=t.id and i.state in ('completed','not_applicable'))::int "checklistComplete",(select count(*) from workflow_task_checklist_items i where i.task_id=t.id)::int "checklistTotal",coalesce((select json_agg(json_build_object('id',i.id,'label',i.label,'state',i.state) order by i.sort_order) from workflow_task_checklist_items i where i.task_id=t.id),'[]'::json) checklist from workflow_tasks t join loans l on l.id=t.loan_id left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where t.state not in ('completed','cancelled','not_applicable') ${ownerWhere} order by case when t.state='past_due' or (t.due_at is not null and t.due_at<now()) then 0 when t.state='action_required' then 1 when t.state='follow_up_due' or (t.next_follow_up_at is not null and t.next_follow_up_at<=now()) then 2 when t.state='due_soon' then 3 when t.state in ('blocked','escalated') then 4 when t.state='waiting' then 5 else 6 end,coalesce(t.next_follow_up_at,t.due_at) asc nulls last`,params);return {viewer:{email:employee.email,role:employee.role},tasks:result.rows.map(row=>({...row,priority:row.state==='past_due'||(row.dueAt&&new Date(row.dueAt)<new Date())?'past_due':row.state==='waiting'&&row.nextFollowUpAt&&new Date(row.nextFollowUpAt)<=new Date()?'follow_up_due':row.state}))};}
  async myWorkEmployees({employee}){if(employee.role!=='admin')throw new Error('Not authorized for employee filters');const result=await this.pool.query(`select distinct e.email,e.display_name "displayName",e.role from employees e join workflow_tasks t on lower(t.owner_email)=e.email where e.active=true and t.state not in ('completed','cancelled','not_applicable') and t.owner_role in ('processor','processor_assistant') order by e.display_name,e.email`);return {employees:result.rows};}
  async authorizedWorkflowTask(client,employee,taskId){const result=await client.query('select * from workflow_tasks where id=$1',[taskId]),task=result.rows[0];if(!task)throw new Error('Workflow task not found');if(employee.role==='admin')return task;if(task.owner_role!==employee.role||String(task.owner_email??'').toLowerCase()!==String(employee.email).toLowerCase())throw new Error('Not authorized for this workflow task');return task;}
  async mutateWorkflowTask({employee,taskId,action,blockedCategory=null,note=null,checklistItemId=null,checklistState=null,at=new Date().toISOString()}){const client=await this.pool.connect();try{await client.query('begin');const task=await this.authorizedWorkflowTask(client,employee,taskId);if(action==='follow_up'){if(!task.follow_up_cadence_business_days)throw new Error('Task has no follow-up cadence');const next=nextFollowUpAt(at,task.follow_up_cadence_business_days,this.calendar);await client.query("update workflow_tasks set state='waiting',last_follow_up_at=$2,next_follow_up_at=$3,follow_up_count=follow_up_count+1,updated_at=now() where id=$1",[taskId,at,next]);await this.addWorkflowHistory(client,taskId,{at,action:'followed_up',fromState:task.state,toState:'waiting',actorEmail:employee.email,note});}else if(action==='complete'||action==='payoff_received'){const items=await client.query('select state from workflow_task_checklist_items where task_id=$1',[taskId]);if(items.rowCount&&!checklistComplete(items.rows))throw new Error('Complete or mark not applicable every checklist item first');await client.query("update workflow_tasks set state='completed',completed_at=$2,updated_at=now() where id=$1",[taskId,at]);await this.addWorkflowHistory(client,taskId,{at,action:action==='payoff_received'?'payoff_received':'completed',fromState:task.state,toState:'completed',actorEmail:employee.email,note});}else if(action==='block'){if(!['borrower','vendor','lender','ARIVE/system','internal','other'].includes(blockedCategory))throw new Error('Blocked category is required');await client.query("update workflow_tasks set state='blocked',blocked_at=$2,blocked_category=$3,blocked_reason=$4,blocked_by_email=$5,updated_at=now() where id=$1",[taskId,at,blockedCategory,note,employee.email]);await this.addWorkflowHistory(client,taskId,{at,action:'blocked',fromState:task.state,toState:'blocked',actorEmail:employee.email,note,metadata:{}});}else if(action==='unblock'){const state=task.next_follow_up_at?'waiting':'action_required';await client.query('update workflow_tasks set state=$2,blocked_at=null,blocked_category=null,blocked_reason=null,blocked_by_email=null,updated_at=now() where id=$1',[taskId,state]);await this.addWorkflowHistory(client,taskId,{at,action:'unblocked',fromState:task.state,toState:state,actorEmail:employee.email,note});}else if(action==='payoff_ordered'){if(task.task_type!=='order_payoff')throw new Error('Payoff action is not valid for this task');const next=nextFollowUpAt(at,3,this.calendar);await client.query("update workflow_tasks set state='waiting',last_follow_up_at=$2,next_follow_up_at=$3,follow_up_count=0,updated_at=now() where id=$1",[taskId,at,next]);await this.addWorkflowHistory(client,taskId,{at,action:'payoff_ordered',fromState:task.state,toState:'waiting',actorEmail:employee.email,note});}else if(action==='checklist'){const item=await client.query('select * from workflow_task_checklist_items where id=$1 and task_id=$2',[checklistItemId,taskId]);if(!item.rowCount||!['action_required','completed','not_applicable'].includes(checklistState))throw new Error('Invalid checklist update');if(checklistState==='not_applicable'&&!(/Flood Cert|HOA Cert/i.test(item.rows[0].label)||task.task_type==='hoa_condo'))throw new Error('This checklist item is required');await client.query('update workflow_task_checklist_items set state=$2,completed_at=case when $2 in (\'completed\',\'not_applicable\') then $3 else null end,completed_by_email=case when $2 in (\'completed\',\'not_applicable\') then $4 else null end where id=$1',[checklistItemId,checklistState,at,employee.email]);await this.addWorkflowHistory(client,taskId,{at,action:'checklist_changed',actorEmail:employee.email,metadata:{}});}else throw new Error('Invalid workflow action');await client.query('commit');return {ok:true};}catch(error){await client.query('rollback');throw error;}finally{client.release();}}
  async createManualWorkflow({employee,loanId,type,checklist=[]}){if(!['processor','admin'].includes(employee.role)||!['ready_for_resubmittal','appraisal_correction','hoa_condo'].includes(type))throw new Error('Not authorized for this workflow action');const client=await this.pool.connect(),at=new Date().toISOString();try{await client.query('begin');const loan=await client.query("select l.id,coalesce(e.metadata->>'assistantEmail','') assistant_email,coalesce(e.metadata->>'assistant','') assistant_name from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where l.id=$1",[loanId]);if(!loan.rowCount)throw new Error('Loan not found');const config={ready_for_resubmittal:{taskType:'resubmit_conditions_to_uw',title:'Re-submit Conditions to UW',ownerRole:'processor',ownerEmail:employee.email,ownerName:employee.displayName,dueAt:businessDeadline(at,0,this.calendar),cadence:null,waitingOn:null,origin:'manual'},appraisal_correction:{taskType:'appraisal_correction',title:'Request appraisal correction',ownerRole:'processor_assistant',ownerEmail:loan.rows[0].assistant_email||null,ownerName:loan.rows[0].assistant_name||null,dueAt:businessDeadline(at,2,this.calendar),cadence:2,waitingOn:'appraiser',origin:'conditional'},hoa_condo:{taskType:'hoa_condo',title:'HOA / Condo requirements',ownerRole:'processor_assistant',ownerEmail:loan.rows[0].assistant_email||null,ownerName:loan.rows[0].assistant_name||null,dueAt:businessDeadline(at,3,this.calendar),cadence:3,waitingOn:'hoa_management',origin:'conditional'}}[type];if(config.ownerRole==='processor_assistant'&&!config.ownerEmail)throw new Error('Processor Assistant assignment is required');const created=await client.query(`insert into workflow_tasks(id,loan_id,task_type,title,origin,owner_role,owner_email,owner_name,state,created_at,due_at,kpi_eligible,waiting_on,follow_up_cadence_business_days,metadata) values($1,$2,$3,$4,$5,$6,$7,$8,'action_required',$9,$10,false,$11,$12,'{}') on conflict(loan_id,task_type) do nothing returning id`,[randomUUID(),loanId,config.taskType,config.title,config.origin,config.ownerRole,config.ownerEmail,config.ownerName,at,config.dueAt,config.waitingOn,config.cadence]);if(created.rowCount){await this.addWorkflowHistory(client,created.rows[0].id,{at,action:type==='ready_for_resubmittal'?'ready_for_resubmittal':'manual_task_created',actorEmail:employee.email});if(type==='hoa_condo')for(const [index,label] of checklist.filter(label=>typeof label==='string'&&label.length>0&&label.length<=120&&!/@|\b(ssn|dob|borrower)\b/i.test(label)).entries())await client.query('insert into workflow_task_checklist_items(id,task_id,label,sort_order) values($1,$2,$3,$4)',[randomUUID(),created.rows[0].id,label.trim(),index]);}await client.query('commit');return {ok:true,created:Boolean(created.rowCount)};}catch(error){await client.query('rollback');throw error;}finally{client.release();}}
  async createVictoryEvent(executor,{eventType,loanId=null,displayLoanId=null,occurredAt,metadata,dedupeKey}){if(!victorySettings.enabled||!victorySettings.supportedEventTypes.includes(eventType))return false;const result=await executor.query('insert into victory_events(id,event_type,loan_id,display_loan_id,occurred_at,metadata,dedupe_key) values($1,$2,$3,$4,$5,$6,$7) on conflict(dedupe_key) do nothing returning id',[randomUUID(),eventType,loanId,displayLoanId,occurredAt,safeVictoryMetadata(metadata),dedupeKey]);return Boolean(result.rowCount);}
  async fundingAggregateFor(executor,year,month){const result=await executor.query(fundingAggregateSql,[year,month]),row=result.rows[0]??{count:0,volume:0,missingAmountCount:0};return {count:Number(row.count),volume:Number(row.volume),missingAmountCount:Number(row.missingAmountCount)};}
  async fundingSummaryFor(executor,year,month){const [goal,actuals]=await Promise.all([executor.query('select funded_loan_goal "fundedLoanGoal",funded_volume_goal "fundedVolumeGoal" from monthly_funding_goals where year=$1 and month=$2',[year,month]),this.fundingAggregateFor(executor,year,month)]);return fundingGoalSummary({year,month,goal:goal.rows[0]??null,actualCount:actuals.count,actualVolume:actuals.volume,missingAmountCount:actuals.missingAmountCount});}
  async syncVictoryEvents(executor,{loanId,eventType,occurredAt,displayLoanId,fundingBefore=null}){if(!victorySettings.enabled)return;if(eventType==='LOAN_FUNDED'){const safeLoan=(await executor.query('select state,loan_amount from loans where id=$1',[loanId])).rows[0]??{};await this.createVictoryEvent(executor,{eventType:'loan_funded',loanId,displayLoanId,occurredAt,metadata:{state:safeLoan.state,loanAmount:Number(safeLoan.loan_amount)},dedupeKey:`funded:${loanId}`});}if(eventType==='CLEAR_TO_CLOSE'){const uw=await executor.query("select occurred_at from loan_stage_events where loan_id=$1 and event_type='UNDERWRITING_SUBMITTED' order by occurred_at asc limit 1",[loanId]),elapsed=quickCtcElapsedCalendarDays(uw.rows[0]?.occurred_at,occurredAt);if(elapsed!==null&&elapsed<=victorySettings.quickCtcCalendarDays)await this.createVictoryEvent(executor,{eventType:'quick_ctc',loanId,displayLoanId,occurredAt,metadata:{elapsedCalendarDays:elapsed},dedupeKey:`quick-ctc:${loanId}`});}if(eventType==='LOAN_FUNDED'&&fundingBefore){const {year,month}=fundingBefore,current=pacificYearMonth();if(year===current.year&&month===current.month){const after=await this.fundingSummaryFor(executor,year,month);if(goalWasCrossed(fundingBefore.fundedCount.actual,after.fundedCount.actual,after.fundedCount.goal))await this.createVictoryEvent(executor,{eventType:'funding_count_goal_hit',occurredAt,metadata:{fundedCount:after.fundedCount.actual,goal:after.fundedCount.goal,year,month},dedupeKey:`funding-count-goal:${year}-${String(month).padStart(2,'0')}`});if(goalWasCrossed(fundingBefore.fundedVolume.actual,after.fundedVolume.actual,after.fundedVolume.goal))await this.createVictoryEvent(executor,{eventType:'funding_volume_goal_hit',occurredAt,metadata:{fundedVolume:after.fundedVolume.actual,goal:after.fundedVolume.goal,year,month},dedupeKey:`funding-volume-goal:${year}-${String(month).padStart(2,'0')}`});}}}
  async receive(payload,receivedAt=new Date().toISOString()) {
    const client=await this.pool.connect(),id=randomUUID(),key=payloadIdempotencyKey(payload);
    try {
      await client.query('BEGIN');
      await client.query('insert into inbound_events (id,source,external_id,idempotency_key,payload_hash,received_at,payload,processing_status) values ($1,$2,$3,$4,$5,$6,$7,$8)',[id,'zapier-arive',key,key,payloadFingerprint(payload),receivedAt,redactedAuditPayload(payload,receivedAt),'received']);
      const claim=await client.query('insert into webhook_idempotency (source,idempotency_key,first_audit_id) values ($1,$2,$3) on conflict do nothing returning idempotency_key',['zapier-arive',key,id]);
      if(!claim.rowCount){await client.query("update inbound_events set processing_status='duplicate',processed_at=$2 where id=$1",[id,receivedAt]);await client.query('COMMIT');return {ok:true,outcome:'duplicate',tasksCreated:0};}
      const loan=normalizeArivePayload(payload,receivedAt);
      if(!loan.systemGuid)return await this.fail(client,id,receivedAt,'Missing ARIVE System GUID');
      await client.query(`insert into loans (id,arive_system_guid,arive_display_loan_id,loan_number,purpose,mortgage_type,city,state,current_stage,created_at,updated_at,borrower_first_name,borrower_last_name) values ($1,$2,$3,$3,$4,$5,$6,$7,$8,$9,$9,$10,$11) on conflict (arive_system_guid) do update set arive_display_loan_id=excluded.arive_display_loan_id,purpose=excluded.purpose,mortgage_type=excluded.mortgage_type,city=excluded.city,state=excluded.state,current_stage=excluded.current_stage,borrower_first_name=coalesce(excluded.borrower_first_name,loans.borrower_first_name),borrower_last_name=coalesce(excluded.borrower_last_name,loans.borrower_last_name),updated_at=excluded.updated_at`,[randomUUID(),loan.systemGuid,loan.displayLoanId,loan.purpose,loan.mortgageType,loan.city,loan.state,loan.currentStatus??'UNKNOWN',receivedAt,loan.borrowerFirstName??null,loan.borrowerLastName??null]);
      const row=await client.query('select id from loans where arive_system_guid=$1',[loan.systemGuid]),loanId=row.rows[0].id,eventType=supportedEventType(loan.currentStatus);
      if(!eventType||!loan.statusAt){const tasksCreated=await this.syncClosingDisclosureTask(client,loanId,null,loan.milestoneDates);await reconcileAriveMilestones(client,{loanId,milestoneDates:loan.milestoneDates,trackerContext:loan.trackerContext});await client.query("update inbound_events set processing_status='processed',failure_reason=$2,processed_at=$3 where id=$1",[id,eventType?'Missing Current Loan Status Date; no milestone created':'No supported status event',receivedAt]);await client.query('COMMIT');return {ok:true,outcome:'accepted-no-event',tasksCreated};}
      const eventId=randomUUID(),fundingPeriod=eventType==='LOAN_FUNDED'?pacificYearMonth(new Date(loan.statusAt)):null,fundingBefore=fundingPeriod?{...fundingPeriod,...await this.fundingSummaryFor(client,fundingPeriod.year,fundingPeriod.month)}:null;
      const stage=await client.query('insert into loan_stage_events (id,loan_id,event_type,occurred_at,received_at,source,source_event_id,metadata) values ($1,$2,$3,$4,$5,$6,$7,$8) on conflict do nothing returning id',[eventId,loanId,eventType,loan.statusAt,receivedAt,'zapier-arive',key,{ariveDisplayLoanId:loan.displayLoanId,processor:loan.processor,processorEmail:loan.processorEmail,assistant:loan.assistant,assistantEmail:loan.assistantEmail,assignmentException:loan.assistantException,loanTeamRoles:loan.teamUsers}]);
      await this.syncWorkflowForEvent(client,{loanId,eventType,occurredAt:loan.statusAt,eventId,processor:loan.processor,processorEmail:loan.processorEmail,assistant:loan.assistant,assistantEmail:loan.assistantEmail});
      let tasksCreated=0;
      if(eventType==='UNDERWRITING_SUBMITTED')for(const milestone of assistantMilestones){const completedAt=loan.milestoneDates[milestone.completionKey]??null,deadline=dueAt(loan.statusAt,{kind:'businessHours',value:milestone.businessDays*8.5},this.calendar).toISOString(),created=await client.query(`insert into assistant_tasks (id,loan_id,task_type,applicable_at,due_at,completed_at,status,created_from_event_id) values ($1,$2,$3,$4,$5,$6,$7,$8) on conflict (loan_id,task_type) do nothing returning id`,[randomUUID(),loanId,milestone.type,loan.statusAt,deadline,completedAt,completedAt?'completed':'open',eventId]);tasksCreated+=created.rowCount;}
      tasksCreated+=await this.syncClosingDisclosureTask(client,loanId,eventId,loan.milestoneDates);
      await reconcileAriveMilestones(client,{loanId,milestoneDates:loan.milestoneDates,trackerContext:loan.trackerContext});
      if(stage.rowCount)await this.syncVictoryEvents(client,{loanId,eventType,occurredAt:loan.statusAt,displayLoanId:loan.displayLoanId,fundingBefore});
      await client.query("update inbound_events set processing_status='processed',processed_at=$2 where id=$1",[id,receivedAt]);await client.query('COMMIT');return {ok:true,outcome:'processed',tasksCreated};
    } catch(error){await client.query('ROLLBACK');throw error;} finally {client.release();}
  }
  async fail(client,id,receivedAt,reason){await client.query("update inbound_events set processing_status='failed',failure_reason=$2,processed_at=$3 where id=$1",[id,reason,receivedAt]);await client.query('COMMIT');return {ok:false,outcome:'failed',error:reason};}
  async listLoans(search=''){const term=`%${search}%`;const result=await this.pool.query(`select l.id,l.arive_display_loan_id,l.current_stage,l.city,l.state,coalesce(e.metadata->>'processor','Unassigned') processor,coalesce(e.metadata->>'assistant','Unassigned') assistant,(select task_type from assistant_tasks t where t.loan_id=l.id and t.completed_at is null order by t.due_at asc nulls last limit 1) next_milestone,(select due_at from assistant_tasks t where t.loan_id=l.id and t.completed_at is null order by t.due_at asc nulls last limit 1) next_due_at from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where coalesce(l.arive_display_loan_id,'') ilike $1 or coalesce(l.current_stage,'') ilike $1 or coalesce(l.city,'') ilike $1 or coalesce(l.state,'') ilike $1 or coalesce(e.metadata->>'processor','') ilike $1 or coalesce(e.metadata->>'assistant','') ilike $1 order by l.updated_at desc limit 250`,[term]);return {source:'live',loans:result.rows.map(row=>this.safeLoanRow(row))};}
  safeLoanRow(row){const due=row.next_due_at?new Date(row.next_due_at):null,now=new Date();const slaStatus=!due?'On Track':due<now?'Breached':due-now<.2*(due-new Date(now.getTime()-8.5*3600000))?'Due Soon':'On Track';return {loanKey:row.id,displayLoanId:row.arive_display_loan_id??'—',processor:row.processor,assistant:row.assistant,currentStage:row.current_stage,cityState:[row.city,row.state].filter(Boolean).join(', ')||'—',nextMilestone:row.next_milestone?.replaceAll('_',' ')??'—',slaStatus};}
  async loanDetail(loanKey){const loan=await this.pool.query(`select l.id,l.arive_display_loan_id,l.current_stage,l.city,l.state,coalesce(e.metadata->>'processor','Unassigned') processor,coalesce(e.metadata->>'assistant','Unassigned') assistant from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where l.id=$1`,[loanKey]);if(!loan.rowCount)return null;const tasks=await this.pool.query(`select task_type,due_at,completed_at,status from assistant_tasks where loan_id=$1 order by due_at asc`,[loanKey]),processorSlas=await this.pool.query(`select r.metric_key,m.due_at,m.state from sla_measurements m join sla_rules r on r.id=m.rule_id where m.loan_id=$1 order by m.due_at asc`,[loanKey]);const detail=this.safeLoanRow(loan.rows[0]);return {...detail,processorSlas:processorSlas.rows.map(item=>({name:item.metric_key.replaceAll('_',' '),dueAt:item.due_at,status:item.state})),milestones:tasks.rows.map(task=>({name:task.task_type.replaceAll('_',' '),dueAt:task.due_at,completedAt:task.completed_at,status:task.completed_at?'Completed':new Date(task.due_at)<new Date()?'Breached':new Date(task.due_at)-new Date()<8.5*3600000?'Due Soon':'On Track'}))};}
  async fundingAggregate(year,month){return this.fundingAggregateFor(this.pool,year,month);}
  async fundingSummary(year,month){return this.fundingSummaryFor(this.pool,year,month);}
  async monthlyFundingGoal(year,month){if(year===undefined||month===undefined)({year,month}=pacificYearMonth());return this.fundingSummary(year,month);}
  async saveMonthlyFundingGoal({year,month,fundedLoanGoal,fundedVolumeGoal}){if(!Number.isInteger(year)||!Number.isInteger(month)||month<1||month>12||!Number.isInteger(fundedLoanGoal)||fundedLoanGoal<=0||!Number.isFinite(fundedVolumeGoal)||fundedVolumeGoal<=0)throw new Error('Invalid monthly funding goal');await this.pool.query(`insert into monthly_funding_goals(id,year,month,funded_loan_goal,funded_volume_goal) values($1,$2,$3,$4,$5) on conflict(year,month) do update set funded_loan_goal=excluded.funded_loan_goal,funded_volume_goal=excluded.funded_volume_goal,updated_at=now()`,[randomUUID(),year,month,fundedLoanGoal,fundedVolumeGoal]);return this.monthlyFundingGoal(year,month);}
  async dashboard(){const latest=`left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true`,{year,month}=pacificYearMonth();const [counts,processorLoans,processorSlas,funded,assistantTasks,assistantSlas,processorBreaches,assistantExceptions,ctcRisk,fundingGoal]=await Promise.all([
    this.pool.query(`select count(*) filter(where l.current_stage <> 'LOAN_FUNDED') active_loans,count(*) filter(where l.current_stage='LOAN_SETUP') new_files,count(*) filter(where l.current_stage='UNDERWRITING_SUBMITTED') uw_submitted,count(*) filter(where l.current_stage='CLEAR_TO_CLOSE') clear_to_close,(select count(*) from assistant_tasks t join loans task_loan on task_loan.id=t.loan_id where task_loan.processing_eligible_at is not null and task_loan.kpi_tracking_started_at is not null and t.kpi_eligible and t.completed_at is null and t.due_at<now())+(select count(*) from sla_measurements m join loans sla_loan on sla_loan.id=m.loan_id where sla_loan.processing_eligible_at is not null and sla_loan.kpi_tracking_started_at is not null and m.state='breached') past_sla from loans l where l.processing_eligible_at is not null`),
    this.pool.query(`select l.current_stage "currentStage",coalesce(e.metadata->>'processor','Unassigned') processor from loans l ${latest} where l.processing_eligible_at is not null`),
    this.pool.query(`select coalesce(e.metadata->>'processor','Unassigned') processor,r.metric_key "metricKey",m.state,m.due_at "dueAt",m.evaluated_at "evaluatedAt" from sla_measurements m join sla_rules r on r.id=m.rule_id join loans l on l.id=m.loan_id ${latest} where l.processing_eligible_at is not null and l.kpi_tracking_started_at is not null and r.owner_role='processor'`),
    this.pool.query(`select coalesce(e.metadata->>'processor','Unassigned') processor from loan_stage_events f join loans l on l.id=f.loan_id ${latest} where l.processing_eligible_at is not null and f.event_type='LOAN_FUNDED' and f.occurred_at>=date_trunc('month',now())`),
    this.pool.query(`select coalesce(e.metadata->>'assistant','Unassigned') assistant,t.task_type "taskType",t.kpi_eligible "kpiEligible",t.applicable_at "applicableAt",t.due_at "dueAt",t.completed_at "completedAt" from assistant_tasks t join loans l on l.id=t.loan_id ${latest} where l.processing_eligible_at is not null and t.kpi_eligible`),
    this.pool.query(`select coalesce(e.metadata->>'assistant','Unassigned') assistant,r.metric_key "taskType",m.state,m.due_at "dueAt",m.evaluated_at "evaluatedAt" from sla_measurements m join sla_rules r on r.id=m.rule_id join loans l on l.id=m.loan_id ${latest} where l.processing_eligible_at is not null and l.kpi_tracking_started_at is not null and r.owner_role='assistant'`),
    this.pool.query(`select l.arive_display_loan_id "displayLoanId",coalesce(e.metadata->>'processor','Unassigned') processor,r.metric_key detail,m.due_at "dueAt" from sla_measurements m join sla_rules r on r.id=m.rule_id join loans l on l.id=m.loan_id ${latest} where l.processing_eligible_at is not null and r.owner_role='processor' and m.state='breached' limit 50`),
    this.pool.query(`select l.arive_display_loan_id "displayLoanId",coalesce(e.metadata->>'assistant','Unassigned') assistant,t.task_type detail,t.due_at "dueAt",case when t.due_at<now() then 'assistant-breached' else 'assistant-approaching' end kind from assistant_tasks t join loans l on l.id=t.loan_id ${latest} where l.processing_eligible_at is not null and t.completed_at is null and (t.due_at<now() or now()>=t.applicable_at + (t.due_at-t.applicable_at)*.8) union all select l.arive_display_loan_id,coalesce(e.metadata->>'assistant','Unassigned'),r.metric_key,m.due_at,'assistant-breached' from sla_measurements m join sla_rules r on r.id=m.rule_id join loans l on l.id=m.loan_id ${latest} where l.processing_eligible_at is not null and r.owner_role='assistant' and m.state='breached' limit 50`),
    this.pool.query(`select l.arive_display_loan_id "displayLoanId",coalesce(e.metadata->>'processor','Unassigned') processor,null assistant,'Clear to close' detail,'ctc-risk' kind from loans l ${latest} where l.processing_eligible_at is not null and l.current_stage='CLEAR_TO_CLOSE' and exists(select 1 from sla_measurements m join sla_rules r on r.id=m.rule_id where m.loan_id=l.id and lower(r.metric_key) like '%ctc%' and m.state in ('breached','at-risk')) union all select l.arive_display_loan_id,coalesce(e.metadata->>'processor','Unassigned'),null,'Processor Assistant assignment review','assistant-assignment' from loans l ${latest} where l.processing_eligible_at is not null and coalesce(e.metadata->>'assignmentException','')<>'' limit 50`),
    this.fundingSummary(year,month)
  ]);const c=counts.rows[0];const attention=[...processorBreaches.rows.map(row=>({...row,kind:'processor-breached'})),...assistantExceptions.rows,...ctcRisk.rows].map(row=>({kind:row.kind,displayLoanId:row.displayLoanId??'—',processor:row.processor??null,assistant:row.assistant??null,detail:row.detail?.replaceAll('_',' ')??'Assignment review',dueAt:row.dueAt??null}));return {...buildLiveDashboard({counts:{activeLoans:Number(c.active_loans),newFiles:Number(c.new_files),uwSubmitted:Number(c.uw_submitted),clearToClose:Number(c.clear_to_close),fundedMtd:fundingGoal.fundedCount.actual,pastSla:Number(c.past_sla)},processorLoans:processorLoans.rows,processorSlas:processorSlas.rows,funded:funded.rows,assistantTasks:assistantTasks.rows,assistantSlas:assistantSlas.rows,attention}),fundingGoal};}
  async health(){const q=await this.pool.query(`select count(*) filter(where processing_status='processed') processed,count(*) filter(where processing_status='failed') failed,count(*) filter(where processing_status='duplicate') duplicates,count(*) received,max(received_at) last from inbound_events`),recent=await this.pool.query(`select received_at,external_id,coalesce(payload->>'ariveDisplayLoanId','—') display_loan_id,coalesce(payload->>'currentLoanStatus','—') event_type,processing_status,failure_reason from inbound_events order by received_at desc limit 20`);const r=q.rows[0];return {connectionStatus:Number(r.processed)>0?'arive-connected':'not-connected',lastEventReceived:r.last,eventsReceivedToday:Number(r.received),eventsProcessed:Number(r.processed),failedEvents:Number(r.failed),duplicateEventsIgnored:Number(r.duplicates),loansSynced:Number((await this.pool.query('select count(*) count from loans')).rows[0].count),missingRequiredFields:0,recent:recent.rows.map(row=>({receivedAt:row.received_at,sourceEventId:row.external_id,ariveDisplayLoanId:row.display_loan_id,eventType:row.event_type,status:row.processing_status,auditNote:row.failure_reason??'Processed'}))};}
  async victoryEvents(after){if(!after||Number.isNaN(new Date(after).getTime()))return {events:[]};const result=await this.pool.query(`select id,event_type "eventType",display_loan_id "displayLoanId",occurred_at "occurredAt",created_at "createdAt",metadata from victory_events where created_at>$1 order by created_at asc limit 20`,[after]);return {events:result.rows.map(row=>({id:row.id,eventType:row.eventType,displayLoanId:row.displayLoanId??null,occurredAt:row.occurredAt,createdAt:row.createdAt,metadata:safeVictoryMetadata(row.metadata)}))};}
  /** Last definition deliberately scopes the operational File Detail to eligible loans. */
  async listLoans(search=''){
    const term=`%${search}%`;
    const result=await this.pool.query(`select l.id,l.arive_display_loan_id,l.current_stage,l.city,l.state,coalesce(e.metadata->>'processor','Unassigned') processor,coalesce(e.metadata->>'assistant','Unassigned') assistant,(select task_type from assistant_tasks t where t.loan_id=l.id and t.completed_at is null order by t.due_at asc nulls last limit 1) next_milestone,(select due_at from assistant_tasks t where t.loan_id=l.id and t.completed_at is null order by t.due_at asc nulls last limit 1) next_due_at from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where l.processing_eligible_at is not null and (coalesce(l.arive_display_loan_id,'') ilike $1 or coalesce(l.current_stage,'') ilike $1 or coalesce(l.city,'') ilike $1 or coalesce(l.state,'') ilike $1 or coalesce(e.metadata->>'processor','') ilike $1 or coalesce(e.metadata->>'assistant','') ilike $1) order by l.updated_at desc limit 250`,[term]);
    return {source:'live',loans:result.rows.map(row=>this.safeLoanRow(row))};
  }
  async loanDetail(loanKey){
    const loan=await this.pool.query(`select l.id,l.arive_display_loan_id,l.current_stage,l.city,l.state,coalesce(e.metadata->>'processor','Unassigned') processor,coalesce(e.metadata->>'assistant','Unassigned') assistant from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true where l.id=$1 and l.processing_eligible_at is not null`,[loanKey]);
    if(!loan.rowCount)return null;
    const tasks=await this.pool.query(`select task_type,due_at,completed_at,status from assistant_tasks where loan_id=$1 order by due_at asc`,[loanKey]),processorSlas=await this.pool.query(`select r.metric_key,m.due_at,m.state from sla_measurements m join sla_rules r on r.id=m.rule_id where m.loan_id=$1 order by m.due_at asc`,[loanKey]);
    const detail=this.safeLoanRow(loan.rows[0]);
    return {...detail,processorSlas:processorSlas.rows.map(item=>({name:item.metric_key.replaceAll('_',' '),dueAt:item.due_at,status:item.state})),milestones:tasks.rows.map(task=>({name:task.task_type.replaceAll('_',' '),dueAt:task.due_at,completedAt:task.completed_at,status:task.completed_at?(new Date(task.completed_at)<=new Date(task.due_at)?'Completed':'Completed Late'):new Date(task.due_at)<new Date()?'Breached':new Date(task.due_at)-new Date()<8.5*3600000?'Due Soon':'On Track'}))};
  }
  async hydrateWorkflowTasks({dryRun=true,now=new Date().toISOString()}={}){const client=await this.pool.connect();try{await client.query('begin');const rows=await client.query(`select l.id,l.arive_display_loan_id "displayLoanId",l.current_stage stage,l.purpose,coalesce(e.metadata->>'processorEmail','') processor_email,coalesce(e.metadata->>'processor','') processor_name,coalesce(e.metadata->>'assistantEmail','') assistant_email,coalesce(e.metadata->>'assistant','') assistant_name,coalesce(i.payload->'milestoneDates','{}'::jsonb) "milestoneDates" from loans l left join lateral (select metadata from loan_stage_events where loan_id=l.id order by occurred_at desc,received_at desc limit 1) e on true left join lateral (select payload from inbound_events where source='zapier-arive' and payload->>'ariveSystemGuid'=l.arive_system_guid order by received_at desc,id desc limit 1) i on true where l.processing_eligible_at is not null`),exists=await client.query('select loan_id,task_type from workflow_tasks'),known=new Set(exists.rows.map(row=>`${row.loan_id}:${row.task_type}`)),planned=[],skipped=[];for(const loan of rows.rows){const plan=planHydratedWorkflow({stage:loan.stage,purpose:loan.purpose,milestoneDates:loan.milestoneDates,processor:{email:loan.processor_email,name:loan.processor_name},assistant:{email:loan.assistant_email,name:loan.assistant_name},now});for(const item of plan.tasks){if(known.has(`${loan.id}:${item.type}`))skipped.push({displayLoanId:loan.displayLoanId,taskType:item.type,reason:'existing workflow task'});else planned.push({loan,item});}for(const reason of plan.skipped)skipped.push({displayLoanId:loan.displayLoanId,reason});}if(!dryRun)for(const {loan,item} of planned){const created=await client.query(`insert into workflow_tasks(id,loan_id,task_type,title,origin,owner_role,owner_email,owner_name,state,created_at,due_at,kpi_eligible,waiting_on,follow_up_cadence_business_days,next_follow_up_at,metadata) values($1,$2,$3,$4,'automatic',$5,$6,$7,$8,$9,$10,false,$11,$12,$13,$14) on conflict(loan_id,task_type) do nothing returning id`,[randomUUID(),loan.id,item.type,item.title,item.ownerRole,item.ownerEmail,item.ownerName,item.state,now,item.dueAt,item.waitingOn,item.followUpCadenceBusinessDays,item.nextFollowUpAt,item.metadata]);if(created.rowCount)await this.addWorkflowHistory(client,created.rows[0].id,{at:now,action:'operational_hydration_created',toState:item.state,metadata:{sourceEvent:'persisted_production_pipeline_state'}});}if(dryRun)await client.query('rollback');else await client.query('commit');const grouped=key=>planned.reduce((all,row)=>{const value=key(row)??'Unassigned';all[value]=(all[value]??0)+1;return all;},{});return {dryRun,processingEligibleLoansInspected:rows.rowCount,tasksWouldCreate:planned.length,byTaskType:grouped(row=>row.item.type),byOwnerRole:grouped(row=>row.item.ownerRole),byOwnerEmail:grouped(row=>row.item.ownerEmail??'Unassigned'),tasks:planned.map(row=>({displayLoanId:row.loan.displayLoanId,currentStage:row.loan.stage,proposedTask:row.item.type,owner:row.item.ownerEmail,proposedState:row.item.state,dueAt:row.item.dueAt,nextFollowUpAt:row.item.nextFollowUpAt,kpiEligible:false,reason:row.item.reason})),skipped};}catch(error){await client.query('rollback');throw error;}finally{client.release();}}
}
